with shipments_by_order as (select order_id, min(delivered_date) as min_delivered_date, round((100 * sum(case when status = 'RETURNED' then 1 else 0 end)) / count(*), 1) as pct_returned from shipments where status = 'DELIVERED' group by order_id) select o.amount, sbo.min_delivered_date, sbo.pct_returned from orders o inner join shipments_by_order sbo on o.id = sbo.order_id order by amount desc;
